contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 id) public {
        require(to != address(0), "to zero");
        require(from != address(0), "from zero");

        // Mint token `id` to `from`. If this reverts then the token id already exists
        // and the transferFrom precondition below cannot be established.
        bool minted;
        try c.transferFrom(from, to, id) {
            minted = true;
        } catch {
            minted = false;
        }

        // Ensure the token actually exists and is owned by `from` before the real call.
        if (!minted) {
            // fall through: no state changed by the failed transferFrom (reverted)
        }
        require(c.ownerOf(id) == from, "need owner from");

        // From is the current owner so this call is authorized and must succeed.
        c.transferFrom(from, to, id);

        // After a successful transfer the approval slot for the token must be cleared.
        assert(c.getApproved(id) == address(0));
    }
}

