contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address to, uint256 id) public {
        require(caller != address(0), "caller zero");
        require(to != address(0), "to zero");

        uint256 ownerNftId;
        try c.ownerOf(id) returns (uint256 oid) {
            ownerNftId = oid;
        } catch {
            ownerNftId = 0;
        }
        require(ownerNftId != 0, "NFT must be minted");

        address ownerBefore;
        try c.ownerOf(id) returns (uint256 oid) {
            ownerBefore = c.ownerOf(id);
        } catch {
            ownerBefore = address(0);
        }

        bool unauthorized = msg.sender != ownerBefore && !c.isApprovedForAll(ownerBefore, msg.sender) && msg.sender != c.getApproved(id);

        bool reverted;
        try c.safeTransferFrom(ownerBefore, to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (unauthorized) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(c.ownerOf(id) != ownerBefore);
            assert(c.getApproved(id) == address(0));
            assert(c.ownerOf(id) == to);
        }
    }
}

