        require(caller != address(0), "zero caller");

        address ownerBefore = c.owner();
        bool callerIsOwner = (caller == ownerBefore);

        // The msg.sender is always address(this) for direct calls.
        // If address(this) is not the owner, the call must revert.
        // If address(this) is the owner, the call must succeed.
        bool thisIsOwner = (address(this) == ownerBefore);

        bool reverted;
        try c.renounceOwnership() {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        assert(reverted == !thisIsOwner && (reverted ? ownerAfter == ownerBefore : ownerAfter == address(0)));
    }

